insert into public.lf_recipes (brand_id, title, slug, species_id, prep_time_min, cook_time_min, servings, cooking_method, ingredients, steps, recommended_spice, recommended_marinade, safety_notes, is_active) values
('22222222-2222-2222-2222-222222222222','Grilled Chambo with Lemon & Garlic','grilled-chambo-lemon-garlic','c82fcdc5-2519-48af-b7f2-8afb4a49a4b2',15,20,4,'Grill','["1 kg Chambo","2 tbsp LakeFresh Lemon & Garlic Spice","2 cloves garlic","1 lemon","Salt to taste"]'::jsonb,'["Clean and scale the Chambo.","Rub with spice, garlic and lemon juice.","Grill 8-10 min per side until cooked through.","Serve hot."]'::jsonb,'LakeFresh Lemon & Garlic','LakeFresh Lemon & Garlic Marinade','Cook fish to an internal temperature of 63°C. Refrigerate leftovers within 2 hours.','true'),
('22222222-2222-2222-2222-222222222222','Fried Chambo','fried-chambo','c82fcdc5-2519-48af-b7f2-8afb4a49a4b2',10,15,4,'Fry','["1 kg Chambo","2 tbsp LakeFresh Hot & Spicy","Oil for frying","Salt"]'::jsonb,'["Clean and dry the fish.","Season with spice and salt.","Fry in hot oil until golden and cooked through.","Drain and serve."]'::jsonb,'LakeFresh Hot & Spicy','LakeFresh Peri-Peri Marinade','Ensure oil is hot before frying. Do not reuse oil multiple times.','true'),
('22222222-2222-2222-2222-222222222222','Baked Chambo with Herbs','baked-chambo-herbs','c82fcdc5-2519-48af-b7f2-8afb4a49a4b2',15,25,4,'Bake','["1 kg Chambo","2 tbsp LakeFresh Original Fish Spice","Mixed herbs","Olive oil","Salt"]'::jsonb,'["Preheat oven to 180°C.","Season fish and drizzle with oil.","Bake 20-25 min until flaky.","Serve with vegetables."]'::jsonb,'LakeFresh Original Fish Spice','LakeFresh Herb & Garlic Marinade','Bake until flesh is opaque and flakes easily.','true'),
('22222222-2222-2222-2222-222222222222','Chambo Curry','chambo-curry','c82fcdc5-2519-48af-b7f2-8afb4a49a4b2',20,30,4,'Stew','["1 kg Chambo","2 tbsp LakeFresh Curry Seasoning","Tomatoes","Onion","Coconut milk"]'::jsonb,'["Saute onion and tomatoes.","Add curry seasoning and coconut milk.","Add fish and simmer 15-20 min.","Serve with rice or nsima."]'::jsonb,'LakeFresh Curry Seasoning','LakeFresh Spicy Tomato Marinade','Simmer gently to avoid breaking the fish.','true'),
('22222222-2222-2222-2222-222222222222','BBQ Chambo','bbq-chambo','c82fcdc5-2519-48af-b7f2-8afb4a49a4b2',15,20,4,'Grill','["1 kg Chambo","2 tbsp LakeFresh BBQ Seasoning","BBQ sauce","Lemon"]'::jsonb,'["Season fish with BBQ rub.","Grill and baste with BBQ sauce.","Serve with lemon wedges."]'::jsonb,'LakeFresh BBQ Seasoning','LakeFresh BBQ Fish Marinade','Keep grill at medium heat to avoid burning sugar.','true');
insert into public.lf_recipes (brand_id, title, slug, species_id, prep_time_min, cook_time_min, servings, cooking_method, ingredients, steps, recommended_spice, recommended_marinade, safety_notes, is_active) values
('22222222-2222-2222-2222-222222222222','Grilled Micheni with Peri-Peri','grilled-micheni-peri-peri','99d78cd6-9c50-4b0e-a761-00032e233a92',15,18,4,'Grill','["1 kg Micheni","2 tbsp LakeFresh Hot & Spicy","LakeFresh Peri-Peri Marinade","Salt"]'::jsonb,'["Clean the fish.","Marinate in peri-peri 30 min.","Grill 7-9 min per side.","Serve hot."]'::jsonb,'LakeFresh Hot & Spicy','LakeFresh Peri-Peri Marinade','Marinate in the fridge, not at room temperature.','true'),
('22222222-2222-2222-2222-222222222222','Fried Micheni','fried-micheni','99d78cd6-9c50-4b0e-a761-00032e233a92',10,15,4,'Fry','["1 kg Micheni","2 tbsp LakeFresh Original Fish Spice","Oil for frying","Salt"]'::jsonb,'["Clean and dry fish.","Season and fry until golden.","Drain and serve."]'::jsonb,'LakeFresh Original Fish Spice','LakeFresh BBQ Fish Marinade','Fry in small batches for even cooking.','true'),
('22222222-2222-2222-2222-222222222222','BBQ Micheni','bbq-micheni','99d78cd6-9c50-4b0e-a761-00032e233a92',15,20,4,'Grill','["1 kg Micheni","2 tbsp LakeFresh BBQ Seasoning","BBQ marinade","Lemon"]'::jsonb,'["Rub with BBQ seasoning.","Grill and baste.","Serve with lemon."]'::jsonb,'LakeFresh BBQ Seasoning','LakeFresh BBQ Fish Marinade','Avoid flare-ups from dripping marinade.','true'),
('22222222-2222-2222-2222-222222222222','Micheni Stew','micheni-stew','99d78cd6-9c50-4b0e-a761-00032e233a92',20,30,4,'Stew','["1 kg Micheni","2 tbsp LakeFresh Curry Seasoning","Tomatoes","Onion","Spicy tomato marinade"]'::jsonb,'["Saute onion and tomatoes.","Add curry seasoning and marinade.","Add fish and simmer.","Serve with nsima."]'::jsonb,'LakeFresh Curry Seasoning','LakeFresh Spicy Tomato Marinade','Simmer gently to keep fish intact.','true'),
('22222222-2222-2222-2222-222222222222','Baked Micheni with Lemon','baked-micheni-lemon','99d78cd6-9c50-4b0e-a761-00032e233a92',15,22,4,'Bake','["1 kg Micheni","2 tbsp LakeFresh Lemon & Garlic","Lemon slices","Herb marinade"]'::jsonb,'["Season fish and top with lemon.","Drizzle herb marinade.","Bake 20 min at 180°C.","Serve warm."]'::jsonb,'LakeFresh Lemon & Garlic','LakeFresh Herb & Garlic Marinade','Bake until flesh flakes easily.','true');
insert into public.lf_recipes (brand_id, title, slug, species_id, prep_time_min, cook_time_min, servings, cooking_method, ingredients, steps, recommended_spice, recommended_marinade, safety_notes, is_active) values
('22222222-2222-2222-2222-222222222222','Fried Usipa','fried-usipa','5cf8c1e8-fb73-4101-818a-429372bb299f',10,12,4,'Fry','["500 g Usipa","LakeFresh Original Fish Spice","Oil for frying","Salt"]'::jsonb,'["Rinse Usipa.","Season lightly.","Fry until crisp and golden.","Drain and serve with nsima."]'::jsonb,'LakeFresh Original Fish Spice','LakeFresh Herb & Garlic Marinade','Fry in small batches; do not overcrowd.','true'),
('22222222-2222-2222-2222-222222222222','Usipa Curry','usipa-curry','5cf8c1e8-fb73-4101-818a-429372bb299f',15,20,4,'Stew','["500 g Usipa","LakeFresh Curry Seasoning","Tomatoes","Onion","Coconut milk"]'::jsonb,'["Saute onion and tomatoes.","Add curry seasoning and coconut milk.","Add Usipa and simmer 10-12 min.","Serve with rice."]'::jsonb,'LakeFresh Curry Seasoning','LakeFresh Spicy Tomato Marinade','Simmer gently to avoid overcooking.','true'),
('22222222-2222-2222-2222-222222222222','Grilled Usipa Skewers','grilled-usipa-skewers','5cf8c1e8-fb73-4101-818a-429372bb299f',15,10,4,'Grill','["500 g Usipa","LakeFresh Lemon & Garlic","Lemon juice","Skewers"]'::jsonb,'["Thread Usipa on skewers.","Brush with lemon-garlic marinade.","Grill 4-5 min per side.","Serve hot."]'::jsonb,'LakeFresh Lemon & Garlic','LakeFresh Lemon & Garlic Marinade','Soak wooden skewers before grilling.','true'),
('22222222-2222-2222-2222-222222222222','Spicy Usipa','spicy-usipa','5cf8c1e8-fb73-4101-818a-429372bb299f',10,12,4,'Fry','["500 g Usipa","LakeFresh Hot & Spicy","Oil for frying"]'::jsonb,'["Season Usipa with hot & spicy.","Fry until crisp.","Serve as a snack or side."]'::jsonb,'LakeFresh Hot & Spicy','LakeFresh Peri-Peri Marinade','Fry in small batches for crispiness.','true'),
('22222222-2222-2222-2222-222222222222','Usipa with Nsima','usipa-nsima','5cf8c1e8-fb73-4101-818a-429372bb299f',15,20,4,'Stew','["500 g Usipa","LakeFresh Original Fish Spice","Tomatoes","Onion","Nsima to serve"]'::jsonb,'["Saute onion and tomatoes.","Add spice and a little water.","Add Usipa and simmer 10 min.","Serve with nsima."]'::jsonb,'LakeFresh Original Fish Spice','LakeFresh Spicy Tomato Marinade','Simmer gently; Usipa cooks quickly.','true');
